begin;
set local statement_timeout='25s';
create temp table venue_create_results(test text,passed boolean) on commit drop;
grant insert,select on venue_create_results to authenticated,anon;
do $$
declare
 c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid();
 a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); pa uuid; pb uuid;
 v uuid; w uuid; f uuid; g uuid; h uuid; s uuid; t uuid; u uuid;
 denied boolean; n bigint; baseline bigint; created uuid;
begin
 if exists(select 1 from cron.job where active) then raise exception 'Disable cron before test'; end if;
 select count(*) into baseline from public.notification_queue;
 insert into public.clubs(id,name) values(c,'ROLLBACK publication own'),(d,'ROLLBACK publication foreign');
 insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data) values
 (a,a::text||'@example.invalid','{"display_name":"Publication admin"}','{}'),
 (b,b::text||'@example.invalid','{"display_name":"Publication foreign reserve"}','{}');
 select id into pa from public.member_profiles where user_id=a;
 select id into pb from public.member_profiles where user_id=b;
 insert into public.club_memberships(club_id,member_profile_id,role,is_active) values(c,pa,'admin',true),(d,pb,'member',true);
 insert into public.venues(club_id,name,is_home_venue) values(c,'Rollback own venue',false) returning id into v;
 insert into public.venues(club_id,name,is_home_venue) values(d,'Rollback foreign venue',false) returning id into w;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(c,now()+interval '30 days',false,v,1,4) returning id into f;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(c,now()+interval '31 days',false,v,1,4) returning id into h;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(d,now()+interval '32 days',false,w,1,4) returning id into g;
 insert into public.team_selections(fixture_id) values(f) returning id into s;
 insert into public.team_selections(fixture_id) values(g) returning id into t;
 insert into public.team_selections(fixture_id) values(h) returning id into u;
 insert into public.team_selection_members(team_selection_id,member_profile_id,role,is_selected) values(s,pa,'reserve',true),(t,pb,'reserve',true);
 reset role;
 update public.club_memberships set role='member',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue member denied',denied);
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full member denied',denied);
 reset role;
 update public.club_memberships set role='guest',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue guest denied',denied);
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full guest denied',denied);
 reset role;
 update public.club_memberships set role='admin',is_active=false where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue inactive admin denied',denied);
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full inactive admin denied',denied);
 reset role;
 update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue foreign admin denied',denied);
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full foreign admin denied',denied);
 reset role;
 update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims','{}',true);
 set local role anon;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue anonymous denied',denied);
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied venue',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full anonymous denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 created:=public.create_club_venue(c,'Rollback admin create_club_venue',false);
 reset role;
 insert into venue_create_results select 'create_club_venue admin creates own external',club_id=c and not is_home_venue from public.venues where id=created;
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied home',true); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue admin home denied',denied);
 denied:=false; begin perform public.create_club_venue(d,'Rollback denied foreign',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue admin foreign denied',denied);
 created:=public.create_club_venue_full(c,'Rollback admin create_club_venue_full',false);
 reset role;
 insert into venue_create_results select 'create_club_venue_full admin creates own external',club_id=c and not is_home_venue from public.venues where id=created;
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied home',true); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full admin home denied',denied);
 denied:=false; begin perform public.create_club_venue_full(d,'Rollback denied foreign',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full admin foreign denied',denied);
 reset role; update public.club_memberships set role='selector',is_active=true where club_id=c and member_profile_id=pa;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 created:=public.create_club_venue(c,'Rollback selector create_club_venue',false);
 reset role;
 insert into venue_create_results select 'create_club_venue selector creates own external',club_id=c and not is_home_venue from public.venues where id=created;
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue(c,'Rollback denied home',true); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue selector home denied',denied);
 denied:=false; begin perform public.create_club_venue(d,'Rollback denied foreign',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue selector foreign denied',denied);
 created:=public.create_club_venue_full(c,'Rollback selector create_club_venue_full',false);
 reset role;
 insert into venue_create_results select 'create_club_venue_full selector creates own external',club_id=c and not is_home_venue from public.venues where id=created;
 set local role authenticated;
 denied:=false; begin perform public.create_club_venue_full(c,'Rollback denied home',true); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full selector home denied',denied);
 denied:=false; begin perform public.create_club_venue_full(d,'Rollback denied foreign',false); exception when insufficient_privilege then denied:=true; end; insert into venue_create_results values('create_club_venue_full selector foreign denied',denied);
 reset role; insert into public.app_superusers(user_id) values(a); set local role authenticated;
 created:=public.create_club_venue(d,'Rollback super create_club_venue',true);
 reset role; insert into venue_create_results select 'create_club_venue superuser creates foreign home',club_id=d and is_home_venue from public.venues where id=created; set local role authenticated;
 created:=public.create_club_venue_full(d,'Rollback super create_club_venue_full',true);
 reset role; insert into venue_create_results select 'create_club_venue_full superuser creates foreign home',club_id=d and is_home_venue from public.venues where id=created; set local role authenticated;
 reset role;
 insert into venue_create_results values('cron remains disabled',not exists(select 1 from cron.job where active));
 if exists(select 1 from venue_create_results where not passed) then raise exception 'Venue creation checks failed'; end if;
end $$;
select * from venue_create_results;
rollback;
